-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "ruRU" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.mop.monk.brewmaster.Name"] = "Рекомендуемая"
L["rm.mop.monk.brewmaster.Description"] = "Выбирается автоматически при специализации «Хмелевар». Поддерживает Скрытые резервы Нокаутирующим ударом, использует Удар бочонком всякий раз, когда для его ци есть место, Устранение вреда, когда вы ранены (сразу при здоровье ниже 35%), Дзуки для траты энергии, Лапу тигра ради Силы тигра и как бесплатный заполнитель (до 34 уровня ци набирает Дзуки) и Смертельное касание, когда его можно применить. С дистанции вне боя: Волна ци, Хмельная дымка, Столкновение или Удар бочонком. Против трёх и более врагов: Порыв нефритового ветра, Пламенное дыхание и Танцующий журавль — только пока у Скрытых резервов есть запас времени. Напоминания: Стойка упорного быка, Наследие императора, Очищающий отвар при Сильном пошатывании (при Умеренном, когда Скрытые резервы накоплены), Отвар неуловимости от шести наложений, Защита при Мощной защите, Отвар ци, Сюэнь, Укрепляющий отвар, Смягчение удара или Распыление магии при низком здоровье, Рука-копье. Напоминание о статуе черного быка выключено; Отведение ударов, Дзен-медитация и Вызов остаются за вами."
L["rm.mop.monk.brewmaster.offensive.Name"] = "Сначала урон (симулятор)"
L["rm.mop.monk.brewmaster.offensive.Description"] = "Альтернатива встроенной ротации «Хмелевар», по умолчанию выключена: включите её и выключите ту или повысьте её приоритет. Следует списку симулятора с упором на урон для танка, чьё снаряжение превосходит контент: Порыв нефритового ветра перед Ударом бочонком, ци тратится на Нокаутирующий удар ради урона, без регулярного Очищающего отвара и Защиты (Очищающий отвар подсвечивается только при срабатывании Очищения от комплекта T15). Отвар неуловимости, Отвар ци, Сюэнь и Укрепляющий отвар по-прежнему остаются напоминаниями."
L["rm.mop.monk.mistweaver.Name"] = "Рекомендуемая"
L["rm.mop.monk.mistweaver.Description"] = "Выбирается автоматически при специализации «Ткач туманов». С дружественной целью лечит её: Заживляющий туман по готовности, Духовный подъем, когда ранены три и более союзника рядом, Устранение вреда и ваш талант ци ради ци, Порыв нефритового ветра или Танцующий журавль для раненой группы, Благотворный туман при пяти наложениях Живительного тумана, Успокаивающий туман, когда у цели меньше 80% здоровья, затем Окутывающий туман и Благотворный туман во время его поддержания. С враждебной целью лечит кулаками (fistweaving): Лапа тигра и Нокаутирующий удар при Мышечной памяти для поддержания Силы тигра и Змеиного рвения, Нокаутирующий удар при полной ци, Благотворный туман при пяти наложениях Живительного тумана, Заживляющий туман и Устранение вреда ради ци, Дзуки. Напоминания: Стойка мудрой змеи, Наследие императора, статуя Нефритовой Змеи в группе, Маначай в спокойные моменты, Громовой чай, Отвар ци, Исцеляющий кокон на союзника ниже 35%, Сюэнь, Детоксикация, защитные способности, Рука-копье. Кого лечить, выбираете вы; Восстановление сил (напоминание выключено) и Целительная сфера остаются за вами."
L["rm.mop.monk.unspecialized.Name"] = "До выбора специализации"
L["rm.mop.monk.unspecialized.Description"] = "Для уровней 1–9 или любого монаха, который не выбрал специализацию; встроенная ротация специализации вступает в силу, как только вы её выберете. Поддерживает Стойку разъяренного тигра и Силу тигра, тратит две ци на Нокаутирующий удар, использует Устранение вреда, когда вы ранены, иначе Дзуки."
L["rm.mop.monk.windwalker.Name"] = "Рекомендуемая"
L["rm.mop.monk.windwalker.Description"] = "Выбирается автоматически при специализации «Танцующий с ветром». Смертельное касание, когда его можно применить, Лапа тигра для поддержания Силы тигра, Удар восходящего солнца по готовности, Волна ци, срабатывания Неожиданного приема, Неистовые кулаки, когда вы стоите на месте и их поддержание не переполнит энергию, Дзуки, когда не хватает двух ци (при ранении — Устранение вреда вместо него), Нокаутирующий удар, если он не оставит без ци следующий Удар восходящего солнца. Против двух и более врагов Удар восходящего солнца поддерживает свой отрицательный эффект, а с трёх добавляется Танцующий журавль или Порыв нефритового ветра. Напоминания: Стойка разъяренного тигра, Наследие императора и Наследие Белого Тигра, Отвар тигриной силы при 19 наложениях (при 15, если есть ци для траты, при 10 под Жаждой крови или в конце боя), Будоражащий отвар при малом запасе энергии, Отвар ци, Сюэнь, «Буря, земля и огонь» против двух врагов (применяете его на второго), Закон кармы, защитные способности и Рука-копье. Проверки переполнения энергии — это пороги энергии, поэтому подстройте их под свою скорость."
L["rm.mop.monk.windwalker.simc.Name"] = "SimulationCraft 5.4.8 (Hekili и MaxDps)"
L["rm.mop.monk.windwalker.simc.Description"] = "Альтернатива встроенной ротации «Танцующий с ветром», по умолчанию выключена: включите её и выключите ту или повысьте её приоритет. Исходный список SimulationCraft, который поставляется с аддонами Hekili и MaxDps: Сила тигра обновляется за три секунды, Удар восходящего солнца первым, пока нет его отрицательного эффекта, Неистовые кулаки приберегаются для Отвара тигриной силы (активного или при 15 наложениях), Отвар тигриной силы при 20 наложениях или при 15, если есть ци и действуют оба положительных эффекта. Против трёх и более врагов тратит ресурсы на Танцующего журавля, использует Удар восходящего солнца только при полной ци и копит энергию ниже 60."
L["rm.retail.monk.brewmaster.Name"] = "Боевой помощник Blizzard с отварами"
L["rm.retail.monk.brewmaster.Description"] = "Рекомендуется для специализации «Хмелевар». Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете или поддерживаете заклинание, ротация ждёт. Боевой помощник не применяет отвары, поэтому, как советует Icy Veins, отвары даны напоминаниями рядом с ним: Отвар Черного Быка, «Призыв Нюцзао, Черного Быка», Очищающий отвар, Божественный отвар или Небесное насыщение и Смертельное касание загораются по готовности в бою (Rotation Master пока не может читать Пошатывание, поэтому насколько оно тяжёлое — решать вам). Также Рука-копье против прерываемого заклинания, а Укрепляющий отвар и ваша расовая способность — по готовности в бою; в бою заклинания противников скрыты, поэтому прерывание загорается только там, где игра их показывает, а здоровье на Retail скрыто, поэтому момент для Укрепляющего отвара — на ваше усмотрение."
L["rm.retail.monk.brewmaster.guide.Name"] = "Для справки (Icy Veins)"
L["rm.retail.monk.brewmaster.guide.Description"] = "Только для справки, по умолчанию выключена: приоритет «Хмелевара» по Icy Veins (SimulationCraft в целом согласен). Серия нокаутов, Пустой бочонок и заряды скрыты в бою в Midnight, поэтому ротация не может там работать. Начало боя: Удар бочонком. Нокаутирующий удар; Выброс ци (Мастер гармонии); Лапа тигра при Серии нокаутов; Удар бочонком при полных зарядах или с Пустым бочонком; Пламенное дыхание; Порыв нефритового ветра перед Взрывным бочонком; Выброс ци (Шадо-Пан); Удар бочонком; Порыв нефритового ветра и Танцующий журавль против трёх и более врагов; Лапа тигра; Устранение вреда. Напоминания: Отвар Черного Быка, когда Очищающий и Божественный отвары потрачены, «Призыв Нюцзао, Черного Быка», Очищающий отвар, Божественный отвар или Небесное насыщение, Смертельное касание, а также вспомогательные напоминания."
L["rm.retail.monk.initial.Name"] = "Боевой помощник Blizzard"
L["rm.retail.monk.initial.Description"] = "Рекомендуется до выбора специализации (пока игра сообщает начальную специализацию монаха). Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — общие напоминания всех встроенных ротаций монаха, каждое — как только вы знаете соответствующее заклинание. Когда на 10 уровне вы выбираете специализацию, её встроенные ротации вступают в силу."
L["rm.retail.monk.mistweaver.Name"] = "Для справки (Icy Veins)"
L["rm.retail.monk.mistweaver.Description"] = "Только для справки, по умолчанию выключена. У Blizzard нет списка Боевого помощника для лекарей, а в бою в Midnight здоровье ваших союзников, заряды Заживляющего тумана, наложения Маначая и срабатывания скрыты от аддонов, поэтому советы по лечению невозможны; выбирайте лечение сами. Против враждебной цели предлагает заполнители для лечения кулаками (fistweaving): Удар восходящего солнца, Нокаутирующий удар и Лапа тигра; с дружественной целью или без цели не предлагает ничего. Напоминания: Рука-копье, а Укрепляющий отвар и ваша расовая способность — по готовности в бою."
L["rm.retail.monk.windwalker.Name"] = "Боевой помощник Blizzard"
L["rm.retail.monk.windwalker.Description"] = "Рекомендуется для специализации «Танцующий с ветром». Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight (он уже соблюдает «Искусность: серия ударов»); пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — напоминания о том, что Боевой помощник оставляет вам: Зенит, Небесный проводник, «Призыв Сюэня, Белого Тигра» и Закон кармы в бою, Рука-копье против прерываемого заклинания, а Укрепляющий отвар и ваша расовая способность — по готовности в бою. В бою заклинания противников скрыты, поэтому прерывание загорается только там, где игра его показывает; на Retail здоровье скрыто, поэтому момент для Укрепляющего отвара — на ваше усмотрение."
L["rm.retail.monk.windwalker.guide.Name"] = "Для справки (Icy Veins и SimulationCraft)"
L["rm.retail.monk.windwalker.guide.Description"] = "Только для справки, по умолчанию выключена: приоритет Проводника Небожителей по Icy Veins. Каждый шаг соблюдает «Искусность: серия ударов» (никогда не повторяет последнее применённое заклинание); ци и ваши собственные заклинания остаются видимыми, но Сердце Нефритовой Змеи, Зенит, «Нокаутирующий удар!» и Танец Чи-Цзи скрыты в бою в Midnight, поэтому ротация не может там работать; энергия на Retail скрыта, поэтому Лапа тигра до переполнения энергии опущена. Удар крутящегося дракона, когда до Сюэня больше 10 секунд; Топот зенита при нехватке ци или в конце Зенита; Небесный проводник без Сердца; Неистовые кулаки в конце Сердца; Небесный проводник, «Призыв Сюэня, Белого Тигра», Неистовые кулаки, Удар крутящегося дракона, Удар Владыки Ветра; Нокаутирующий удар, когда ци не хватает на Неистовые кулаки; Удар порыва ветра, Удар восходящего солнца; Нокаутирующий удар при двух зарядах «Нокаутирующий удар!» или во время Зенита; Танцующий журавль во время Зенита или при Танце Чи-Цзи; Смертельное касание; Лапа тигра, Нокаутирующий удар, Пронизывающие ветра как заполнители. Напоминание: Закон кармы, а также вспомогательные напоминания."
